(function() {
    'use strict';
    
    const ramadanPerlis = [
        {day:'Khamis',ramadan:1,date:'19 Feb',imsak:'06:26',berbuka:'19:31'},
        {day:'Jumaat',ramadan:2,date:'20 Feb',imsak:'06:26',berbuka:'19:31'},
        {day:'Sabtu',ramadan:3,date:'21 Feb',imsak:'06:26',berbuka:'19:31'},
        {day:'Ahad',ramadan:4,date:'22 Feb',imsak:'06:26',berbuka:'19:31'},
        {day:'Isnin',ramadan:5,date:'23 Feb',imsak:'06:26',berbuka:'19:31'},
        {day:'Selasa',ramadan:6,date:'24 Feb',imsak:'06:25',berbuka:'19:31'},
        {day:'Rabu',ramadan:7,date:'25 Feb',imsak:'06:25',berbuka:'19:31'},
        {day:'Khamis',ramadan:8,date:'26 Feb',imsak:'06:25',berbuka:'19:31'},
        {day:'Jumaat',ramadan:9,date:'27 Feb',imsak:'06:25',berbuka:'19:31'},
        {day:'Sabtu',ramadan:10,date:'28 Feb',imsak:'06:25',berbuka:'19:31'},
        {day:'Ahad',ramadan:11,date:'1 Mac',imsak:'06:25',berbuka:'19:30'},
        {day:'Isnin',ramadan:12,date:'2 Mac',imsak:'06:25',berbuka:'19:30'},
        {day:'Selasa',ramadan:13,date:'3 Mac',imsak:'06:24',berbuka:'19:30'},
        {day:'Rabu',ramadan:14,date:'4 Mac',imsak:'06:24',berbuka:'19:30'},
        {day:'Khamis',ramadan:15,date:'5 Mac',imsak:'06:24',berbuka:'19:30'},
        {day:'Jumaat',ramadan:16,date:'6 Mac',imsak:'06:24',berbuka:'19:30'},
        {day:'Sabtu',ramadan:17,date:'7 Mac',imsak:'06:24',berbuka:'19:30'},
        {day:'Ahad',ramadan:18,date:'8 Mac',imsak:'06:23',berbuka:'19:30'},
        {day:'Isnin',ramadan:19,date:'9 Mac',imsak:'06:23',berbuka:'19:29'},
        {day:'Selasa',ramadan:20,date:'10 Mac',imsak:'06:23',berbuka:'19:29'},
        {day:'Rabu',ramadan:21,date:'11 Mac',imsak:'06:23',berbuka:'19:29'},
        {day:'Khamis',ramadan:22,date:'12 Mac',imsak:'06:22',berbuka:'19:29'},
        {day:'Jumaat',ramadan:23,date:'13 Mac',imsak:'06:22',berbuka:'19:29'},
        {day:'Sabtu',ramadan:24,date:'14 Mac',imsak:'06:22',berbuka:'19:29'},
        {day:'Ahad',ramadan:25,date:'15 Mac',imsak:'06:22',berbuka:'19:28'},
        {day:'Isnin',ramadan:26,date:'16 Mac',imsak:'06:21',berbuka:'19:28'},
        {day:'Selasa',ramadan:27,date:'17 Mac',imsak:'06:21',berbuka:'19:28'},
        {day:'Rabu',ramadan:28,date:'18 Mac',imsak:'06:21',berbuka:'19:28'},
        {day:'Khamis',ramadan:29,date:'19 Mac',imsak:'06:21',berbuka:'19:28'},
        {day:'Jumaat',ramadan:30,date:'20 Mac',imsak:'06:20',berbuka:'19:27'}
    ];
    
    document.addEventListener('DOMContentLoaded', function() {
        renderTable();
        startCountdown();
    });
    
    function renderTable() {
        const tbody = document.getElementById('ilmxPerlisTableBody');
        const today = new Date();
        
        let html = '';
        ramadanPerlis.forEach((row, index) => {
            const rowDate = new Date(2026, 1, 19 + index);
            const isToday = rowDate.toDateString() === today.toDateString();
            
            html += `<tr${isToday ? ' class="today"' : ''}>
                <td>${row.day}</td>
                <td>${row.ramadan} Ramadan</td>
                <td>${row.date} 2026</td>
                <td class="time-col">${row.imsak}</td>
                <td class="time-col">${row.berbuka}</td>
            </tr>`;
        });
        
        tbody.innerHTML = html;
    }
    
    function startCountdown() {
        const today = new Date();
        const ramadanStart = new Date(2026, 1, 19);
        const daysDiff = Math.floor((today - ramadanStart) / (1000 * 60 * 60 * 24));
        
        if (daysDiff < 0 || daysDiff >= 30) {
            document.getElementById('ilmxPerlisToday').innerHTML = 
                '<strong>Ramadan 2026 bermula 19 Feb - Indera Kayangan!</strong>';
            return;
        }
        
        const todayData = ramadanPerlis[daysDiff];
        const berbukaTime = todayData.berbuka.split(':');
        const targetTime = new Date(today.getFullYear(), today.getMonth(), today.getDate(), 
            parseInt(berbukaTime[0]), parseInt(berbukaTime[1]), 0);
        
        document.getElementById('ilmxPerlisToday').innerHTML = 
            `<strong>Hari ini (${todayData.ramadan} Ramadan):</strong> Imsak ${todayData.imsak} | Berbuka ${todayData.berbuka}`;
        
        setInterval(function() {
            const now = new Date();
            const diff = targetTime - now;
            
            if (diff < 0) {
                document.getElementById('ilmxPerlisHours').textContent = '00';
                document.getElementById('ilmxPerlisMinutes').textContent = '00';
                document.getElementById('ilmxPerlisSeconds').textContent = '00';
                return;
            }
            
            const hours = Math.floor(diff / (1000 * 60 * 60));
            const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((diff % (1000 * 60)) / 1000);
            
            document.getElementById('ilmxPerlisHours').textContent = hours.toString().padStart(2, '0');
            document.getElementById('ilmxPerlisMinutes').textContent = minutes.toString().padStart(2, '0');
            document.getElementById('ilmxPerlisSeconds').textContent = seconds.toString().padStart(2, '0');
        }, 1000);
    }
})();
